+
+            let inch_to_mm =
+                run(stem, json!({ "Units": "inch", "EndUnits": "mm" })).expect("inch -> mm notes");
+            let noted: Vec<&str> = inch_to_mm
+                .lines()
+                .filter(|l| l.contains("END UNITS NOT WRITTEN"))
+                .collect();
+            assert_eq!(noted.len(), 1, "{stem}: inch -> mm note:\n{inch_to_mm}");
+        }
+    }
